<?php
require_once __DIR__.'/Life.php';
$db=Life::db();$uid=Life::uid();Life::install($db);$settings=Life::settings($db);$admin=Life::admin();$h=[Life::class,'h'];$error='';
$tabs=['home'=>'Accueil']+array_diff_key(Life::TYPES+['ideas'=>'Boîte à idées'],array_flip($settings['disabled']));if($settings['games'])$tabs['games']='Détente';$view=(string)($_GET['view']??'home');if(!isset($tabs[$view]))$view='home';
if($_SERVER['REQUEST_METHOD']==='POST'){Life::check();try{
 $action=$_POST['action']??'';
 if($action==='idea'&&!in_array('ideas',$settings['disabled'],true)){$body=trim((string)($_POST['body']??''));if(!$body||mb_strlen($body)>3000)throw new InvalidArgumentException('Suggestion invalide.');$db->prepare('INSERT INTO finea_life_ideas(user_id,body) VALUES(?,?)')->execute([$uid,$body]);}
 elseif($action==='vote'&&!in_array('poll',$settings['disabled'],true)){$id=(int)($_POST['id']??0);$q=$db->prepare("SELECT options_json FROM finea_life_posts WHERE id=? AND kind='poll' AND published=1");$q->execute([$id]);$opts=json_decode($q->fetchColumn()?:'[]',true);$choice=filter_var($_POST['choice']??null,FILTER_VALIDATE_INT);if($choice===false||!isset($opts[$choice]))throw new InvalidArgumentException('Choix invalide.');$db->prepare('INSERT INTO finea_life_votes(post_id,user_id,choice) VALUES(?,?,?) ON DUPLICATE KEY UPDATE choice=choice')->execute([$id,$uid,$choice]);}
 else throw new InvalidArgumentException('Action indisponible.');
 header('Location: divertissements.php?view='.($action==='idea'?'ideas':'poll'));exit;
}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
$posts=$db->query('SELECT id,kind,title,body,event_date,mime,options_json FROM finea_life_posts WHERE published=1 ORDER BY created_at DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
$activeMenu='divertissements';$pageTitle='FINEA Life';require __DIR__.'/../decaissement/includes/header.php';require __DIR__.'/../decaissement/includes/navbar.php';
?><link rel="stylesheet" href="life.css"><main class="life"><header class="life-banner"><div><small>FINEA · Espace collaborateur</small><h1>FINEA Life</h1><p>Vie d’entreprise, cohésion et reconnaissance.</p></div><?php if($admin):?><a class="life-btn" href="admin.php">Administration</a><?php endif;?></header>
<div class="life-shell"><aside class="life-sidebar"><small>VIE D’ENTREPRISE</small><nav><?php foreach($tabs as $key=>$label):?><a href="?view=<?=$key?>" class="<?=$view===$key?'selected':''?>" <?=$view===$key?'aria-current="page"':''?>><?=$h($label)?></a><?php endforeach;?></nav></aside><div class="life-content"><?php if($view==='home'):?><section class="life-card"><small>ESPACE COLLABORATEUR</small><h2>Bienvenue dans FINEA Life</h2><p>Retrouvez les informations et initiatives de votre entreprise.</p></section><div class="life-grid"><?php foreach($tabs as $key=>$label):if($key==='home')continue;?><a class="life-card life-shortcut" href="?view=<?=$key?>"><strong><?=$h($label)?></strong><span>Découvrir →</span></a><?php endforeach;?></div><section><h2>Dernières publications</h2><?php $recent=array_slice(array_values(array_filter($posts,static fn($p)=>isset($tabs[$p['kind']]))),0,5);foreach($recent as $p):?><article class="life-card"><small><?=$h($tabs[$p['kind']])?></small><h3><?=$h($p['title'])?></h3><p><?=$h(mb_strimwidth($p['body'],0,160,'…'))?></p><a href="?view=<?=$h($p['kind'])?>">Voir la rubrique →</a></article><?php endforeach;if(!$recent):?><p class="life-card">Les publications de votre entreprise apparaîtront ici.</p><?php endif;?></section><?php endif;?><?php if($error):?><p role="alert"><?=$h($error)?></p><?php endif;?>
<?php foreach(Life::TYPES as $key=>$label):if($view!==$key||in_array($key,$settings['disabled'],true))continue;$items=array_filter($posts,static fn($p)=>$p['kind']===$key);?><section id="<?=$key?>"><h2><?=$h($label)?></h2><div class="life-grid"><?php foreach($items as $p):?><article class="life-card"><?php if($p['mime']):?><img loading="lazy" src="image.php?id=<?=(int)$p['id']?>" alt="<?=$h($p['title'])?>"><?php endif;?><h3><?=$h($p['title'])?></h3><?php if($p['event_date']):?><small><?=$h($p['event_date'])?></small><?php endif;?><p><?=nl2br($h($p['body']))?></p><?php if($key==='poll'):$q=$db->prepare('SELECT choice FROM finea_life_votes WHERE post_id=? AND user_id=?');$q->execute([$p['id'],$uid]);$v=$q->fetchColumn();if($v!==false):?><p>Votre vote a été enregistré.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=Life::csrf()?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><?php foreach(json_decode($p['options_json']??'[]',true)?:[] as $n=>$option):?><label><input type="radio" name="choice" value="<?=$n?>" required> <?=$h($option)?></label><?php endforeach;?><button name="action" value="vote">Voter</button></form><?php endif;endif;?></article><?php endforeach;?><?php if(!$items):?><p class="life-muted">Aucune publication pour le moment.</p><?php endif;?></div></section><?php endforeach;?>
<?php if($view==='ideas'&&!in_array('ideas',$settings['disabled'],true)):?><section id="ideas" class="life-card"><h2>Boîte à idées</h2><p>Votre suggestion est transmise aux administrateurs avec votre identifiant.</p><form method="post"><input type="hidden" name="csrf" value="<?=Life::csrf()?>"><textarea name="body" required maxlength="3000" placeholder="Votre proposition"></textarea><button name="action" value="idea">Envoyer</button></form></section><?php endif;?>
<?php if($view==='games'&&$settings['games']):?><section id="games"><h2>Espace détente</h2><div class="life-grid"><?php foreach(['duel_clavier'=>'Duel clavier','reflex_duel'=>'Réflexes','morpion'=>'Morpion','pendu'=>'Pendu','pierre_feuille_ciseaux'=>'Pierre feuille ciseaux','quatre_indices_un_mot'=>'4 indices 1 mot'] as $file=>$label):?><a class="life-card" href="<?=$file?>.php"><?=$h($label)?></a><?php endforeach;?></div></section><?php endif;?></div></div></main><script src="life.js" defer></script><?php require __DIR__.'/../decaissement/includes/footer.php';?>
